ExpressaoDAX:
VAR MesAnterior =
                    CALCULATE([receita div cpf],
                    DATEADD(DCALENDARIO[Date], -1,MONTH
                      )
                    )

                    RETURN
                    DIVIDE(
                        [receita div cpf] - MesAnterior,MesAnterior,
                        "Sem Vendas"
                    )

VAR PMesAnterior =
                    CALCULATE([% REPRESENTA],
                    DATEADD(DCALENDARIO[Date], -1,MONTH
                      )
                    )

                    RETURN
                    DIVIDE(
                        [% REPRESENTA] - PMesAnterior,PMesAnterior,
                        "Sem Vendas"
                    )
